text:
#messengerBody {
  flex: 1;
}

p {
  margin: 2px 4px;
}

hr {
  inline-size: 100%;
  border-block-start: 1px solid var(--field-border-color);
  border-block-end: 0;
}

:root:not([customtitlebar]) .titlebar-buttonbox-container {
  visibility: collapse;
}

:root:not([sizemode="maximized"]) .titlebar-restore,
:root:is([sizemode="maximized"]) .titlebar-max {
  display: none;
}
